"""Generated by solo-to-scale; edit `templates/tools/release.py` in the plugin, then run upgrade.

The production release. Pull requests keep merging to main on green CI; main collects them, and production is the
`production` branch, which each production host deploys from. A release moves `production` forward to main
(fast-forward only, so production never has work main lacks), tags it `release-YYYYMMDD-HHMM` and lists what it
brings. Two modes, switched by the founder with the repository variable S2S_AUTO_RELEASE (Settings, Secrets and
variables, Actions, Variables):
  batched (unset): nothing reaches production until a founder runs the `release` workflow; running it is the deploy
                   approval. Use it before launch, while production should move only when you say.
  automatic (true): every merge to main is released straight away. Use it once you are live and changes are small.

  python tools/release.py check --actor <login> --event <workflow_dispatch|push>   # exit 0 may release, 4 no
  python tools/release.py run [--ref main] [--summary FILE] [--dry-run]

Fails closed: an unknown actor, a ref that isn't on main or a production branch that has moved away from main
releases nothing. Python 3 standard library plus git.
"""
from __future__ import annotations

import argparse
import datetime as dt
import os
import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402

BRANCH = "production"
OK, NO, ERROR = 0, 4, 5
REF = re.compile(r"^(main|[0-9a-f]{7,40})$")


def may_release(actor: str, event: str, auto: bool, root: Path, repo: str) -> tuple[bool, str]:
    """A founder's manual run always may; a merge may only when the founder switched automatic releases on."""
    if event == "push":
        return (auto, "automatic releases are on" if auto else "automatic releases are off (S2S_AUTO_RELEASE)")
    if event != "workflow_dispatch":
        return False, f"a {event or 'unknown'} event never releases"
    who = approval.founders(approval.policy(root), repo)
    if actor.lower() in who:
        return True, f"{actor} is a founder"
    return False, f"{actor or 'nobody'} is not a founder in founder/gates.json"


def git(root: Path, *args: str) -> str:
    return subprocess.run(["git", "-C", str(root), *args], check=True, capture_output=True, text=True).stdout.strip()


def has(root: Path, ref: str) -> bool:
    return subprocess.run(["git", "-C", str(root), "rev-parse", "-q", "--verify", ref + "^{commit}"],
                          capture_output=True, check=False).returncode == 0


def ancestor(root: Path, a: str, b: str) -> bool:
    return subprocess.run(["git", "-C", str(root), "merge-base", "--is-ancestor", a, b], check=False).returncode == 0


def plan(root: Path, ref: str = "main", remote: str = "origin") -> dict:
    """What a release would do. Raises ValueError when it must not release."""
    if not REF.match(ref):
        raise ValueError(f"release main or a commit on main, not {ref!r}")
    for branch in ("main", BRANCH):   # one at a time: a missing production branch must not stop main's fetch
        subprocess.run(["git", "-C", str(root), "fetch", "--quiet", remote,
                        f"+refs/heads/{branch}:refs/remotes/{remote}/{branch}"], capture_output=True, check=False)
    main = f"{remote}/main"
    if not has(root, main):
        raise ValueError(f"{main} not found")
    target = git(root, "rev-parse", main if ref == "main" else ref)
    if not ancestor(root, target, main):
        raise ValueError(f"{ref} is not on main")
    base = f"{remote}/{BRANCH}"
    first = not has(root, base)
    if not first:
        if git(root, "rev-parse", base) == target:
            return {"target": target, "base": base, "first": False, "changes": [], "nothing": True}
        if not ancestor(root, base, target):
            raise ValueError(f"{BRANCH} has commits that {ref} lacks, or is ahead of it; fix {BRANCH} by hand "
                             "(it should only ever be moved by this release)")
    span = target if first else f"{base}..{target}"
    log = git(root, "log", "--first-parent", "--format=%h %s", "-n", "200", span)
    return {"target": target, "base": base, "first": first, "changes": [ln for ln in log.splitlines() if ln],
            "nothing": False}


def notes(p: dict, tag: str) -> str:
    if p["nothing"]:
        return f"Nothing to release: `{BRANCH}` is already at `{p['target'][:7]}`.\n"
    head = (f"First release: `{BRANCH}` starts at main `{p['target'][:7]}`." if p["first"] else
            f"`{BRANCH}` moves to main `{p['target'][:7]}`, {len(p['changes'])} change(s):")
    lines = [f"## Release {tag}", "", head, ""]
    if not p["first"]:
        lines += [f"- {c}" for c in p["changes"]]
    return "\n".join(lines) + "\n"


def run(root: Path, ref: str, summary: str | None, dry: bool, remote: str = "origin",
        now: dt.datetime | None = None) -> int:
    try:
        p = plan(root, ref, remote)
    except (ValueError, subprocess.CalledProcessError) as e:
        print(f"not released: {e}", file=sys.stderr)
        return ERROR
    tag = "release-" + (now or dt.datetime.now(dt.timezone.utc)).strftime("%Y%m%d-%H%M")
    text = notes(p, tag)
    if not p["nothing"] and not dry:
        git(root, "push", remote, f"{p['target']}:refs/heads/{BRANCH}")
        git(root, "tag", "-a", tag, p["target"], "-m", text)
        git(root, "push", remote, f"refs/tags/{tag}")
    print(("(dry run) " if dry else "") + text)
    if summary:
        with open(summary, "a", encoding="utf-8") as f:
            f.write(text)
    return OK


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[2])
    sub = ap.add_subparsers(dest="cmd", required=True)
    c = sub.add_parser("check")
    c.add_argument("--actor", default="")
    c.add_argument("--event", default="")
    c.add_argument("--root", default=str(s.ROOT))
    r = sub.add_parser("run")
    r.add_argument("--ref", default="main")
    r.add_argument("--summary")
    r.add_argument("--dry-run", action="store_true")
    r.add_argument("--root", default=str(s.ROOT))
    a = ap.parse_args(argv)
    root = Path(a.root)
    if a.cmd == "check":
        auto = os.environ.get("S2S_AUTO_RELEASE", "").strip().lower() == "true"
        ok, why = may_release(a.actor, a.event, auto, root, os.environ.get("GITHUB_REPOSITORY", "/"))
        print(why)
        return OK if ok else NO
    return run(root, a.ref, a.summary, a.dry_run)


if __name__ == "__main__":
    sys.exit(main())
